// Stage 14: real HTTPS socket tests. Uses temporary local test certificates
// generated by openssl and removes the files after the run. No real secrets.
import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,readFileSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {spawnSync} from 'node:child_process';
import {request} from 'node:https';
import {once} from 'node:events';
import {createLockedStagingHttpsServer} from './locked-https.mjs';

const issuer='https://auth.orca.example.invalid';
const mcpResource='https://mcp.stage.example.invalid/mcp';
const HOST='mcp.stage.example.invalid';

function fixtures(t){
  const folder=mkdtempSync(join(tmpdir(),'orca-stage14-'));
  t.after(()=>rmSync(folder,{recursive:true,force:true}));
  const key=join(folder,'key.pem'),cert=join(folder,'cert.pem');
  const out=spawnSync('openssl',[
    'req','-x509','-newkey','rsa:2048','-nodes',
    '-keyout',key,'-out',cert,'-days','1',
    '-subj','/CN='+HOST,'-addext','subjectAltName=DNS:'+HOST
  ],{encoding:'utf8'});
  assert.equal(out.status,0,'openssl required for isolated TLS test');
  return {
    tlsKey:readFileSync(key,'utf8'),
    tlsCertificate:readFileSync(cert,'utf8'),
    issuerOrigin:issuer,mcpResource
  };
}
async function serve(t,config){
  const server=createLockedStagingHttpsServer(config);
  server.listen(0,'127.0.0.1');
  await once(server,'listening');
  t.after(()=>new Promise(resolve=>server.close(resolve)));
  return server.address().port;
}
async function get(port,path,headers={}){
  return new Promise((resolve,reject)=>{
    const req=request({
      hostname:'127.0.0.1',port,method:'GET',path,
      rejectUnauthorized:false,servername:HOST,
      headers:{host:HOST,...headers},
      timeout:4000
    },res=>{
      const buffers=[];
      res.on('data',chunk=>buffers.push(chunk));
      res.on('end',()=>resolve({
        status:res.statusCode,headers:res.headers,
        body:Buffer.concat(buffers).toString('utf8')
      }));
    });
    req.on('timeout',()=>req.destroy(Error('test_https_timeout')));
    req.on('error',reject);
    req.end();
  });
}
test('Stage 14 cannot activate MCP or OAuth even with an explicit flag',t=>{
  const config=fixtures(t);
  for(const override of [{mcpEnabled:true},{issuerEnabled:true},
    {mcpEnabled:'true'},{issuerEnabled:'true'}]){
    assert.throws(()=>createLockedStagingHttpsServer({
      ...config,...override
    }),/stage14_release_must_remain_disabled/);
  }
});
test('real TLS handshake: liveness says locked and no OAuth/MCP endpoint is exposed',async t=>{
  const port=await serve(t,fixtures(t));
  const health=await get(port,'/healthz');
  assert.equal(health.status,200);
  assert.deepEqual(JSON.parse(health.body),{
    service:'orca-mcp-staging',status:'locked'
  });
  assert.equal(health.headers['cache-control'],'no-store');
  assert.equal((await get(port,'/mcp')).status,503);
  assert.equal((await get(port,'/.well-known/oauth-protected-resource/mcp')).status,503);
  assert.equal((await get(port,'/.well-known/oauth-authorization-server')).status,503);
  assert.equal((await get(port,'/healthz',{host:'evil.example.invalid'})).status,503);
  assert.equal((await get(port,'/healthz',{origin:'https://evil.example.invalid'})).status,503);
  assert.equal((await get(port,'/healthz',{cookie:'token=bad'})).status,503);
  assert.equal((await get(port,'/healthz',{'x-forwarded-proto':'http'})).status,200);
});
test('reject absent TLS material, unapproved issuer and noncanonical resource',t=>{
  const config=fixtures(t);
  assert.throws(()=>createLockedStagingHttpsServer({
    ...config,tlsKey:''
  }),/stage14_tls_material_required/);
  assert.throws(()=>createLockedStagingHttpsServer({
    ...config,issuerOrigin:'http://auth.orca.example.invalid'
  }),/stage14_https_origin_required/);
  assert.throws(()=>createLockedStagingHttpsServer({
    ...config,mcpResource:'https://mcp.stage.example.invalid/other'
  }),/stage14_mcp_resource_required/);
  assert.throws(()=>createLockedStagingHttpsServer({
    ...config,issuerOrigin:'https://mcp.stage.example.invalid'
  }),/stage14_separate_issuer_origin_required/);
});
